namespace NoteDesk {
public class TaskItem {
 public string Id=Guid.NewGuid().ToString("N"); public string Text=""; public bool Done;
 public string Due; public int Lead=30; public string Snooze; public bool Reminded;
}
public class Revision { public string At; public string Content; }
public class Note {
 public string Id=Guid.NewGuid().ToString("N"); public string Title="新的便签"; public string Body="";
 public List<TaskItem> Tasks=new List<TaskItem>(); public string State="active"; public string PreviousState="active";
 public string Created=DateTime.Now.ToString("o"); public string Archived; public bool Visible=true; public bool Pinned; public bool PendingArchive;
 public double X=140,Y=120,W=350,H=520,Alpha=.88; public int Color;
 public List<Revision> History=new List<Revision>();
}
public class Database { public int Schema=1; public List<Note> Notes=new List<Note>(); public bool Sound; }
public class ContentRecord { public string Title; public string Body; public List<TaskItem> Tasks; }
public class Store {
 public Database Data=new Database(); public readonly string Root; public string Warning; public static JavaScriptSerializer Json=new JavaScriptSerializer { MaxJsonLength=int.MaxValue, RecursionLimit=150 };
 public Store(string root) { Root=root; Directory.CreateDirectory(root); string f=Path.Combine(root,"notes.json");
  if(File.Exists(f)) { try { Data=Read(f); } catch { try { Data=Read(f+".bak"); Warning="数据文件异常，已从上次备份恢复。"; } catch { throw new InvalidDataException("便签数据无法读取。原文件已保留，请先备份数据目录再重试："+root); } } }
 }
 static Database Read(string f) { var d=Json.Deserialize<Database>(File.ReadAllText(f,Encoding.UTF8)); if(d==null || d.Notes==null || d.Schema!=1) throw new InvalidDataException(); return d; }
 public static string Content(Note n) { return Json.Serialize(new ContentRecord {Title=n.Title,Body=n.Body,Tasks=n.Tasks}); }
 public void Snapshot(Note n) { string content=Content(n); if(n.History.Count==0 || n.History[n.History.Count-1].Content!=content) n.History.Add(new Revision {At=DateTime.Now.ToString("o"),Content=content}); }
 public void Save() { string f=Path.Combine(Root,"notes.json"),tmp=f+".tmp"; var bytes=Encoding.UTF8.GetBytes(Json.Serialize(Data));
  using(var stream=new FileStream(tmp,FileMode.Create,FileAccess.Write,FileShare.None)) { stream.Write(bytes,0,bytes.Length); stream.Flush(true); }
  if(File.Exists(f)) File.Replace(tmp,f,f+".bak",true); else File.Move(tmp,f);
 }
 public void Restore(Note n,Revision r) { Snapshot(n); var c=Json.Deserialize<ContentRecord>(r.Content); n.Title=c.Title; n.Body=c.Body; n.Tasks=c.Tasks; Snapshot(n); Save(); }
 public static DateTime? Parse(string s) { DateTime v; return DateTime.TryParse(s,null,DateTimeStyles.RoundtripKind,out v)?v:(DateTime?)null; }
 public static bool NeedsReminder(TaskItem t,DateTime now) { if(t.Done || t.Reminded) return false; var due=Parse(t.Snooze) ?? (Parse(t.Due).HasValue?Parse(t.Due).Value.AddMinutes(-t.Lead):(DateTime?)null); return due.HasValue && due.Value<=now; }
}
