 public static void WindowTheme(Window window) {window.Style=(Style)Application.Current.Resources[typeof(Window)];}
 static bool keyboardInput;
 public static bool MotionAllowed { get { return !keyboardInput && SystemParameters.ClientAreaAnimation && !Keyboard.IsKeyDown(Key.Enter) && !Keyboard.IsKeyDown(Key.Space) && !Keyboard.IsKeyDown(Key.Escape); } }
 public static DoubleAnimation Motion(double target,int milliseconds) { return new DoubleAnimation(target,TimeSpan.FromMilliseconds(milliseconds)) {EasingFunction=new CubicEase {EasingMode=EasingMode.EaseOut}}; }
 public static void Value(ProgressBar bar,double target,bool animate) { if(animate&&MotionAllowed)bar.BeginAnimation(ProgressBar.ValueProperty,Motion(target,180));else {bar.BeginAnimation(ProgressBar.ValueProperty,null);bar.Value=target;} }
 static void Press(object sender,MouseButtonEventArgs e) {var button=(Button)sender;if(!MotionAllowed||!button.IsEnabled)return;var scale=button.RenderTransform as ScaleTransform;if(scale==null){scale=new ScaleTransform(1,1);button.RenderTransform=scale;button.RenderTransformOrigin=new Point(.5,.5);}scale.BeginAnimation(ScaleTransform.ScaleXProperty,Motion(.97,100));scale.BeginAnimation(ScaleTransform.ScaleYProperty,Motion(.97,100));}
 static void Release(object sender,MouseEventArgs e) {var scale=((Button)sender).RenderTransform as ScaleTransform;if(scale==null)return;if(!MotionAllowed){scale.BeginAnimation(ScaleTransform.ScaleXProperty,null);scale.BeginAnimation(ScaleTransform.ScaleYProperty,null);scale.ScaleX=scale.ScaleY=1;return;}scale.BeginAnimation(ScaleTransform.ScaleXProperty,Motion(1,120));scale.BeginAnimation(ScaleTransform.ScaleYProperty,Motion(1,120));}
 static void WindowLoaded(object sender,RoutedEventArgs e) {var window=(Window)sender;if(e.OriginalSource!=window||window is Manager||window is NoteWindow||!MotionAllowed)return;var content=window.Content as UIElement;if(content!=null)content.BeginAnimation(UIElement.OpacityProperty,new DoubleAnimation(0,1,TimeSpan.FromMilliseconds(200)) {EasingFunction=new CubicEase {EasingMode=EasingMode.EaseOut}});}
 public static Window Dialog(string title,Window owner,double width=460,double height=430) { return new Window {Title=title,Owner=owner,Width=width,Height=height,WindowStartupLocation=WindowStartupLocation.CenterOwner,ResizeMode=ResizeMode.NoResize,ShowInTaskbar=false}; }
 public static string DateLabel(string value) { var d=Store.Parse(value); return d.HasValue?d.Value.ToString("MM/dd HH:mm"):""; }
}
public class DeskApp:Application {
 public Store Store; public Manager Manager; public Dictionary<string,NoteWindow> OpenNotes=new Dictionary<string,NoteWindow>();
 Forms.NotifyIcon tray; DispatcherTimer tick; Dictionary<string,DispatcherTimer> archiveTimers=new Dictionary<string,DispatcherTimer>(); public bool Exiting; public Action UndoAction; public string Toast=""; public bool Preview; internal bool Headless;
 public DeskApp(string root,bool preview) { Preview=preview; Store=new Store(root); ShutdownMode=ShutdownMode.OnExplicitShutdown; UI.Theme(this); }
 public void Start() {
  Manager=new Manager(this); MainWindow=Manager;
  if(!Preview) { tray=new Forms.NotifyIcon {Icon=System.Drawing.Icon.ExtractAssociatedIcon(System.Reflection.Assembly.GetExecutingAssembly().Location),Text="NoteDesk · 留住每一个小小的完成",Visible=true}; var menu=new Forms.ContextMenuStrip();
   menu.Items.Add("新建便签",null,(s,e)=>Dispatcher.Invoke(new Action(()=>NewNote()))); menu.Items.Add("管理便签",null,(s,e)=>Dispatcher.Invoke(new Action(ShowManager))); menu.Items.Add("退出 NoteDesk",null,(s,e)=>Dispatcher.Invoke(new Action(Quit))); tray.ContextMenuStrip=menu; tray.DoubleClick+=(s,e)=>Dispatcher.Invoke(new Action(ShowManager)); }
  foreach(var n in Store.Data.Notes.Where(n=>n.State=="active"&&n.Visible).ToList()) ShowNote(n);
  if(!Headless)Manager.Show(); if(Store.Warning!=null) MessageBox.Show(Store.Warning,"NoteDesk");
  tick=new DispatcherTimer {Interval=TimeSpan.FromSeconds(2)}; tick.Tick+=(s,e)=>CheckReminders(); if(!Preview)tick.Start();
  foreach(var n in Store.Data.Notes.Where(n=>n.State=="active"&&n.PendingArchive&&n.Tasks.Count>0&&n.Tasks.All(t=>t.Done))) ScheduleArchive(n,null);
 }
 public void Save() { try { Store.Save(); } catch(Exception ex) { Toast="保存失败，请检查磁盘空间。"; if(Manager!=null)Manager.Status.Text=Toast; if(!Exiting)MessageBox.Show("便签暂未保存，请勿退出软件。\n"+ex.Message,"保存失败"); throw; } }
 public void Changed(Note n,bool snapshot=true) { if(snapshot)Store.Snapshot(n); Save(); if(Manager!=null)Manager.Refresh(); }
 public Note NewNote() { var n=new Note(); n.X=120+(Store.Data.Notes.Count%7)*32; n.Y=100+(Store.Data.Notes.Count%7)*24; Store.Data.Notes.Add(n); Store.Snapshot(n); Save(); ShowNote(n); Manager.Refresh(); return n; }
 public void ShowManager() { Manager.Show(); Manager.WindowState=WindowState.Normal; Manager.Activate(); Manager.Refresh(); }
 public void ShowNote(Note n) { if(n.State!="active")return; NoteWindow w; if(!OpenNotes.TryGetValue(n.Id,out w)) { w=new NoteWindow(this,n); OpenNotes[n.Id]=w; } n.Visible=true; if(!Headless){w.Show(); w.Activate();} Save(); if(Manager!=null)Manager.Refresh(); }
 public void HideNote(Note n) { n.Visible=false; if(OpenNotes.ContainsKey(n.Id))OpenNotes[n.Id].Hide(); Changed(n,false); }
 public void RefreshNote(Note n) { if(OpenNotes.ContainsKey(n.Id))OpenNotes[n.Id].Rebuild(); Manager.Refresh(); }
 public void Status(string message,Action undo=null) { Toast=message; UndoAction=undo; Manager.Refresh(); }
 public void Archive(Note n,TaskItem last) { CancelArchive(n); n.State="archived"; n.Archived=DateTime.Now.ToString("o"); if(OpenNotes.ContainsKey(n.Id)) { OpenNotes[n.Id].Flush(); OpenNotes[n.Id].Hide(); } Changed(n);
  Action undoArchive=()=>{ if(n.State!="archived")return; if(last!=null){var item=n.Tasks.FirstOrDefault(t=>t.Id==last.Id);if(item!=null)item.Done=false;} n.State="active"; n.Archived=null; ShowNote(n); Changed(n); RefreshNote(n); };
  Status("已归档「"+n.Title+"」",undoArchive);
  if(!Preview)new UndoToast(this,n.Title,undoArchive).Show();
 }
 public void CancelArchive(Note n) { n.PendingArchive=false; if(archiveTimers.ContainsKey(n.Id)) { archiveTimers[n.Id].Stop(); archiveTimers.Remove(n.Id); } }
 public void ScheduleArchive(Note n,TaskItem last) { CancelArchive(n); n.PendingArchive=true; Save(); var t=new DispatcherTimer {Interval=TimeSpan.FromSeconds(3)}; archiveTimers[n.Id]=t; t.Tick+=(s,e)=> { CancelArchive(n); if(n.State=="active"&&n.Tasks.Count>0&&n.Tasks.All(i=>i.Done))Archive(n,last); }; t.Start(); }
 public void Toggle(Note n,TaskItem task,bool done) { task.Done=done; if(!done)CancelArchive(n); Changed(n); if(done&&Store.Data.Sound)System.Media.SystemSounds.Asterisk.Play(); if(done&&n.Tasks.All(t=>t.Done))ScheduleArchive(n,task); }
 public void Delete(Note n) { CancelArchive(n); if(OpenNotes.ContainsKey(n.Id))OpenNotes[n.Id].Flush(); n.PreviousState=n.State; n.State="deleted"; if(OpenNotes.ContainsKey(n.Id))OpenNotes[n.Id].Hide(); Changed(n); Status("已移入回收站",()=>Restore(n)); }
 public void Restore(Note n) { bool fromArchive=n.State=="archived"; n.PendingArchive=false; n.State=n.State=="deleted"?n.PreviousState:"active"; if(n.State=="active") { n.Archived=null; if(fromArchive)foreach(var t in n.Tasks)t.Reminded=true; } Changed(n); if(n.State=="active")ShowNote(n); }
 public void CheckReminders() { var list=new List<Tuple<Note,TaskItem>>(); foreach(var n in Store.Data.Notes.Where(n=>n.State=="active"))foreach(var t in n.Tasks)if(Store.NeedsReminder(t,DateTime.Now)){t.Reminded=true;list.Add(Tuple.Create(n,t));} if(list.Count==0)return; Save(); new ReminderWindow(this,list).Show(); }
 public void Quit() { foreach(var w in OpenNotes.Values)w.Flush(); Save(); Exiting=true; if(tick!=null)tick.Stop(); if(tray!=null)tray.Dispose(); Shutdown(); }
}
